-- 찬양대(choir_video) 테이블 생성 + 초기 데이터 백필: 2025-01-01 ~ 2026-06-30, 총 275건
-- YouTube 재생목록: https://www.youtube.com/playlist?list=PLj3rgPIpeTF0axEgx4eP185-x_zfQ9MfQ
-- youtube_video_id UNIQUE 제약이므로 재실행해도 안전 (CREATE TABLE IF NOT EXISTS + INSERT ... ON DUPLICATE KEY UPDATE)
-- 생성: 2026-07-01, YouTube Data API playlistItems.list 직접 조회 (snippet.publishedAt = 재생목록 등록일 기준)
-- choir_name: 시온찬양대(1부, 구 "원니스"→2026년 개명 통합)/할렐루야찬양대(2부)/주영광찬양대(수요예배)/주일오후찬양대

CREATE TABLE IF NOT EXISTS choir_video (
    id BIGINT NOT NULL AUTO_INCREMENT,
    title VARCHAR(200) NOT NULL,
    youtube_video_id VARCHAR(50) NOT NULL,
    video_url VARCHAR(255),
    thumbnail_url VARCHAR(500),
    published_at DATE,
    choir_name VARCHAR(30),
    created_at DATETIME NOT NULL,
    updated_at DATETIME,
    PRIMARY KEY (id),
    UNIQUE KEY uk_choir_video_youtube_video_id (youtube_video_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ON DUPLICATE KEY UPDATE title=VALUES(title), video_url=VALUES(video_url), thumbnail_url=VALUES(thumbnail_url), published_at=VALUES(published_at), choir_name=VALUES(choir_name), updated_at=NOW();

ON DUPLICATE KEY UPDATE title=VALUES(title), video_url=VALUES(video_url), thumbnail_url=VALUES(thumbnail_url), published_at=VALUES(published_at), choir_name=VALUES(choir_name), updated_at=NOW();

ON DUPLICATE KEY UPDATE title=VALUES(title), video_url=VALUES(video_url), thumbnail_url=VALUES(thumbnail_url), published_at=VALUES(published_at), choir_name=VALUES(choir_name), updated_at=NOW();

ON DUPLICATE KEY UPDATE title=VALUES(title), video_url=VALUES(video_url), thumbnail_url=VALUES(thumbnail_url), published_at=VALUES(published_at), choir_name=VALUES(choir_name), updated_at=NOW();

ON DUPLICATE KEY UPDATE title=VALUES(title), video_url=VALUES(video_url), thumbnail_url=VALUES(thumbnail_url), published_at=VALUES(published_at), choir_name=VALUES(choir_name), updated_at=NOW();

ON DUPLICATE KEY UPDATE title=VALUES(title), video_url=VALUES(video_url), thumbnail_url=VALUES(thumbnail_url), published_at=VALUES(published_at), choir_name=VALUES(choir_name), updated_at=NOW();

